  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel Organization {\n  id        String   @id @default(uuid())\n  name      String\n  bin       String? // Business Identification Number (БИН KZ)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  branches  Branch[]\n  users     User[]\n}\n\nmodel Branch {\n  id              String           @id @default(uuid())\n  organizationId  String\n  name            String\n  address         String?\n  phone           String?\n  organization    Organization     @relation(fields: [organizationId], references: [id])\n  warehouses      Warehouse[]\n  posIntegrations POSIntegration[]\n  users           UserBranch[]\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n}\n\nmodel Warehouse {\n  id        String          @id @default(uuid())\n  branchId  String\n  name      String // e.g. \"Главный склад кухни\", \"Бар\"\n  isMain    Boolean         @default(false)\n  branch    Branch          @relation(fields: [branchId], references: [id])\n  balances  StockBalance[]\n  movements StockMovement[]\n}\n\nmodel User {\n  id             String       @id @default(uuid())\n  organizationId String\n  email          String       @unique\n  phone          String?\n  passwordHash   String\n  fullName       String\n  role           String // OWNER, MANAGER, STOREKEEPER, CHEF\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  branches       UserBranch[]\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n}\n\nmodel UserBranch {\n  userId   String\n  branchId String\n  user     User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  branch   Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@id([userId, branchId])\n}\n\nmodel POSIntegration {\n  id            String   @id @default(uuid())\n  branchId      String\n  provider      String   @default(\"NEXIUM\")\n  apiKey        String\n  apiSecret     String\n  webhookSecret String\n  isActive      Boolean  @default(true)\n  branch        Branch   @relation(fields: [branchId], references: [id])\n  createdAt     DateTime @default(now())\n}\n\nmodel Ingredient {\n  id             String              @id @default(uuid())\n  organizationId String\n  name           String\n  code           String? // SKU\n  category       String // MEAT, VEGETABLES, DAIRY, GROCERY, BEVERAGES, SEMI_FINISHED\n  mainUnit       String // KG, G, L, ML, PCS\n  costPerUnit    Float // Себестоимость KZT за единицу\n  minStockLevel  Float               @default(0.0) // Порог предупреждения\n  lossPercentage Float               @default(0.0) // % отхода (брутто -> нетто)\n  isSemiFinished Boolean             @default(false)\n  subRecipeId    String? // Ссылка на техкарту для полуфабриката\n  balances       StockBalance[]\n  recipeItems    RecipeItem[]\n  movementItems  StockMovementItem[]\n}\n\nmodel MenuItem {\n  id             String      @id @default(uuid())\n  organizationId String\n  posItemId      String      @unique // ID в системе Nexium\n  name           String\n  description    String?\n  category       String\n  sellingPrice   Float // Цена продажи KZT\n  imageUrl       String?\n  isAvailable    Boolean     @default(true)\n  recipeCard     RecipeCard?\n  createdAt      DateTime    @default(now())\n}\n\nmodel RecipeCard {\n  id          String       @id @default(uuid())\n  menuItemId  String?      @unique\n  yieldAmount Float        @default(1.0)\n  yieldUnit   String       @default(\"PCS\")\n  menuItem    MenuItem?    @relation(fields: [menuItemId], references: [id])\n  items       RecipeItem[]\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n}\n\nmodel RecipeItem {\n  id           String     @id @default(uuid())\n  recipeCardId String\n  ingredientId String\n  grossAmount  Float // Брутто (списываемый вес)\n  netAmount    Float // Нетто (чистый вес в блюде)\n  unit         String // KG, G, L, ML, PCS\n  recipeCard   RecipeCard @relation(fields: [recipeCardId], references: [id], onDelete: Cascade)\n  ingredient   Ingredient @relation(fields: [ingredientId], references: [id])\n}\n\nmodel StockBalance {\n  id           String     @id @default(uuid())\n  warehouseId  String\n  ingredientId String\n  quantity     Float // Текущий остаток\n  warehouse    Warehouse  @relation(fields: [warehouseId], references: [id])\n  ingredient   Ingredient @relation(fields: [ingredientId], references: [id])\n\n  @@unique([warehouseId, ingredientId])\n}\n\nmodel StockMovement {\n  id          String              @id @default(uuid())\n  warehouseId String\n  type        String // RECEIPT, AUTO_DEDUCTION, MANUAL_WRITE_OFF, INVENTORY_ADJUST\n  referenceId String? // ID чека Nexium или номер накладной\n  comment     String?\n  createdAt   DateTime            @default(now())\n  warehouse   Warehouse           @relation(fields: [warehouseId], references: [id])\n  items       StockMovementItem[]\n}\n\nmodel StockMovementItem {\n  id              String        @id @default(uuid())\n  stockMovementId String\n  ingredientId    String\n  quantity        Float // Отрицательное = списание, Положительное = приход\n  unitCost        Float // Себестоимость KZT на момент операции\n  stockMovement   StockMovement @relation(fields: [stockMovementId], references: [id], onDelete: Cascade)\n  ingredient      Ingredient    @relation(fields: [ingredientId], references: [id])\n}\n\nmodel DeductionIncident {\n  id             String   @id @default(uuid())\n  receiptId      String\n  ingredientId   String\n  ingredientName String\n  requestedQty   Float\n  availableQty   Float\n  shortageQty    Float\n  createdAt      DateTime @default(now())\n}\n",
